const DATE_RE = /^(\d{2})\.(\d{2})\.(\d{4})$/;

function parseRuDateUtc(value) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return new Date(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()));
  }
  const match = String(value || '').trim().match(DATE_RE);
  if (!match) return null;
  return new Date(Date.UTC(Number(match[3]), Number(match[2]) - 1, Number(match[1])));
}

const PARSED_CHANGES = CBR_KEY_RATE_CHANGES.map((row) => ({
  time: parseRuDateUtc(row.from).getTime(),
  rate: row.rate,
}));

/** Ключевая ставка ЦБ (доля) на дату. */
export function getKeyRateAt(date) {
  const time = parseRuDateUtc(date)?.getTime();
  if (time == null) return PARSED_CHANGES[0].rate;

  let rate = PARSED_CHANGES[0].rate;
  for (const row of PARSED_CHANGES) {
    if (row.time <= time) rate = row.rate;
    else break;
  }
  return rate;
}

/**
 * Даты смены ставки строго внутри интервала (from, to) —
 * точки, с которых начинается новый отрезок при daysBetween(from,to).
 */
export function getKeyRateChangeDatesBetween(from, to) {
  const fromTime = parseRuDateUtc(from)?.getTime();
  const toTime = parseRuDateUtc(to)?.getTime();
  if (fromTime == null || toTime == null || toTime <= fromTime) return [];

  return PARSED_CHANGES
    .filter((row) => row.time > fromTime && row.time < toTime)
    .map((row) => new Date(row.time));
}
