/**
 * Госпошлина по ст. 333.19 НК РФ (ред. с 09.09.2024).
 * claim — полная пошлина по имущественному иску (пп. 1).
 * courtOrder — 50% от неё (пп. 2), заявление о судебном приказе.
 */

function toAmount(value) {
  const num = Number(String(value).replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(num) ? Math.max(0, num) : 0;
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

/** Полная госпошлина по имущественному иску (пп. 1 п. 1 ст. 333.19 НК РФ). */
export function calculateClaimFee(claimAmount) {
  const amount = toAmount(claimAmount);

  if (amount <= 100000) return 4000;
  if (amount <= 300000) return roundMoney(4000 + (amount - 100000) * 0.03);
  if (amount <= 500000) return roundMoney(10000 + (amount - 300000) * 0.025);
  if (amount <= 1000000) return roundMoney(15000 + (amount - 500000) * 0.02);
  if (amount <= 3000000) return roundMoney(25000 + (amount - 1000000) * 0.01);
  if (amount <= 8000000) return roundMoney(45000 + (amount - 3000000) * 0.007);
  if (amount <= 24000000) return roundMoney(80000 + (amount - 8000000) * 0.0035);
  if (amount <= 50000000) return roundMoney(136000 + (amount - 24000000) * 0.003);
  if (amount <= 100000000) return roundMoney(214000 + (amount - 50000000) * 0.002);

  return Math.min(900000, roundMoney(314000 + (amount - 100000000) * 0.0015));
}

/**
 * @param {number|string} claimAmount — цена иска (долг + пеня)
 * @param {{ kind?: 'courtOrder'|'claim' }} [options]
 */
export function calculateStateDuty(claimAmount, options = {}) {
  const kind = options.kind === 'claim' ? 'claim' : 'courtOrder';
  const claim = roundMoney(toAmount(claimAmount));
  const claimFee = calculateClaimFee(claim);
  const amount = kind === 'courtOrder' ? roundMoney(claimFee * 0.5) : claimFee;

  return {
    claimAmount: claim,
    kind,
    claimFee,
    amount,
  };
}

/** a/c — приказ (50%); b/d/e/j — иск / уточнение (100%). */
export function stateDutyKindForStatement(statementType) {
  return ['a', 'c'].includes(statementType) ? 'courtOrder' : 'claim';
}

export function emptyStateDuty() {
  return {
    claimAmount: 0,
    kind: 'courtOrder',
    claimFee: 0,
    amount: 0,
  };
}

/** Формат для PDF: «2 000» / «2 750,50» */
export function formatDutyAmount(value) {
  const num = roundMoney(toAmount(value));
  const isInt = Math.abs(num - Math.round(num)) < 0.005;
  return num.toLocaleString('ru-RU', {
    minimumFractionDigits: isInt ? 0 : 2,
    maximumFractionDigits: isInt ? 0 : 2,
  });
}
