/** Должники для PDF: при опциях 1–2 (блок 3.2*) — из ЕГРН, иначе из п.8. */

export function debtorDisplayName(item) {
  const fio = String(item?.fio || '').trim();
  if (fio) return fio;
  if (item?.type === 'organization' && item.inn) return `ИНН ${item.inn}`;
  return '';
}

export function joinDebtorNames(list) {
  return (list || []).map(debtorDisplayName).filter(Boolean).join(', ');
}

export function resolveDebtors(form = {}) {
  const requirements = String(form.requirements || '');
  const egrnAllowed = requirements === '1' || requirements === '2';
  const egrn = form.egrnOwners;
  const useEgrn =
    egrnAllowed &&
    egrn &&
    !egrn.noRequest &&
    Array.isArray(egrn.items) &&
    egrn.items.some((item) => String(item.fio || item.legalInn || '').trim());

  if (useEgrn) {
    return egrn.items
      .map((item) => {
        const isOrg = item.type === 'organization';
        return {
          type: isOrg ? 'organization' : 'citizen',
          // Для организации в 3.2* есть только ИНН — наименование в анкете не собирается
          fio: isOrg ? '' : String(item.fio || '').trim(),
          birthday: isOrg ? '' : item.birthday || '',
          birthplace: isOrg ? '' : item.birthplace || '',
          inn: isOrg ? item.legalInn || '' : '',
          address: String(item.address || form.premisesAddress || '').trim(),
          snils: isOrg ? '' : item.snils || '',
        };
      })
      .filter((d) => d.fio || d.inn);
  }

  const fromCitizens = (form.debtors || [])
    .map((d) => ({ type: 'citizen', ...d }))
    .filter((d) => String(d?.fio || '').trim() || String(d?.address || '').trim());
  if (fromCitizens.length) return fromCitizens;

  // п.8 для c/e/d (и 8*): DataDebtorRecalc → debtorLoan
  const loan = form.debtorLoan || {};
  if (String(loan.fio || '').trim() || String(loan.address || '').trim() || String(loan.inn || '').trim()) {
    return [
      {
        type: 'citizen',
        fio: String(loan.fio || '').trim(),
        birthday: loan.birthday || '',
        birthplace: loan.birthplace || '',
        inn: loan.inn || '',
        address: String(loan.address || '').trim(),
        snils: '',
      },
    ];
  }

  // п.8 legal: только ИНН организации
  const legalInn = String(form.debtorInn || '').trim();
  if (legalInn) {
    return [{ type: 'organization', fio: '', birthday: '', birthplace: '', inn: legalInn, address: '', snils: '' }];
  }

  return [];
}
