import { gerbBase64 } from '../assets/gerb';
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { debtorDisplayName, joinDebtorNames, resolveDebtors } from '../utils/resolveDebtors';

const PLACEHOLDER_COLOR = '#C00000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  return value ? plain(value) : placeholder(placeholderText);
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [0, 0, 0, 8] };
}

/** Название участка — как в шапке заявления о выдаче с/приказа (мировой). */
function magistrateFromSoyCourt(soyCourt = {}) {
  const raw =
    (soyCourt.match && soyCourt.match.magistrate) ||
    (soyCourt.kind === 'magistrate' ? soyCourt.raw : '') ||
    '';
  if (raw) {
    const chunks = String(raw)
      .split(/\n| {2,}/)
      .map((s) => s.trim())
      .filter(Boolean);
    const courtName = chunks[0] || String(raw).trim();
    const courtAddress = chunks.slice(1).join(', ');
    const localityMatch = String(courtAddress || raw).match(/г\.\s*[^,\n]+/i);
    return {
      courtName,
      locality: localityMatch ? localityMatch[0].trim() : soyCourt.locality || '',
    };
  }
  return {
    courtName: soyCourt.kind === 'magistrate' ? soyCourt.courtName || '' : '',
    locality: soyCourt.kind === 'magistrate' ? soyCourt.locality || '' : '',
  };
}

export function buildCourtOrderPdfDoc(form = {}) {
  const debtors = resolveDebtors(form);
  const debtor = debtors[0] || {};
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const housingPenalty = (form.skanReport && form.skanReport.housingPenalty) || {};
  const stateDuty = (form.skanReport && form.skanReport.stateDuty) || {};
  const soyCourt = form.soyCourt || {};
  const magistrate = magistrateFromSoyCourt(soyCourt);
  const dutyAmount = stateDuty.amount > 0 ? formatDutyAmount(stateDuty.amount) : null;
  const claimantName = String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const claimantFull = [
    claimantName,
    claimantInn ? `ИНН ${claimantInn}` : '',
    claimant.address || '',
    bank.account ? `р/с ${bank.account}` : '',
    bank.bankName || '',
    bank.bik ? `БИК ${bank.bik}` : '',
    bank.corrAccount ? `кор/с ${bank.corrAccount}` : '',
  ]
    .filter(Boolean)
    .join(', ');

  const debtorFios = joinDebtorNames(debtors);
  const debtorFioList = field(debtorFios, 'ФИО должников через запятую');
  const debtorFioBirthday = field(
    debtors
      .map((d) => {
        const name = debtorDisplayName(d);
        if (!name) return '';
        if (d.type === 'organization') return name;
        const birthday = String(d.birthday || '').trim();
        return birthday ? `${name}, ${birthday}` : name;
      })
      .filter(Boolean)
      .join('\n') || null,
    'ФИО, его ДР через запятую – каждый должник с новой строчки'
  );
  const debtorAddress = field(
    String(debtor.address || form.premisesAddress || form.deliveryAddress || form.tkoAddress || '').trim(),
    'адрес квартиры, по которой взыскивается задолженность'
  );

  const claimWithoutDuty =
    housingPenalty.principalTotal > 0 || housingPenalty.penaltyTotal > 0
      ? `за содержание жилого помещения ${formatDutyAmount(housingPenalty.principalTotal || 0)} руб., пеня ${formatDutyAmount(housingPenalty.penaltyTotal || 0)} руб.`
      : '';

  const content = [
    { image: gerbBase64, width: 60, alignment: 'center', margin: [0, 0, 0, 8] },
    { text: 'СУДЕБНЫЙ ПРИКАЗ', alignment: 'center', bold: true, margin: [0, 0, 0, 2] },
    { text: 'ИМЕНЕМ РОССИЙСКОЙ ФЕДЕРАЦИИ', alignment: 'center', bold: true, margin: [0, 0, 0, 16] },

    {
      columns: [
        { text: [placeholder('дата'), plain(' 202'), placeholder('_'), plain(' г.')] },
        {
          text: field(magistrate.locality, 'населенный пункт из адреса с/участка'),
          alignment: 'right',
        },
      ],
      margin: [0, 0, 0, 16],
    },

    bodyParagraph([
      plain('Мировой судья судебного участка '),
      field(magistrate.courtName, 'название участка (из шапки заявления о выдаче с/приказа)'),
    ]),
    bodyParagraph([plain('рассмотрев заявление '), field(claimantName, 'наименование взыскателя')]),
    bodyParagraph([plain('о вынесении судебного приказа о взыскании с '), debtorFioList]),
    bodyParagraph([
      plain('задолженности '),
      field(claimWithoutDuty, 'что взыскивается + в каком размере'),
      plain(' (из просительной части заявления о выдаче с/приказа) – без госпошлины,'),
    ]),
    bodyParagraph([
      plain(
        'исследовав сведения, изложенные в направленном взыскателем заявлении о вынесении судебного приказа и приложенных к нему документах,'
      ),
    ]),
    bodyParagraph([plain('руководствуясь ст. 121, ст. 122 Гражданского процессуального кодекса РФ,')]),

    { text: 'решил:', alignment: 'center', bold: true, margin: [0, 8, 0, 12] },

    bodyParagraph([plain('Взыскать с '), debtorFioList]),
    bodyParagraph([plain('в пользу '), field(claimantName, 'наименование взыскателя')]),
    bodyParagraph([
      plain('задолженность '),
      field(claimWithoutDuty, 'что взыскивается + в каком размере'),
      plain(' (из просительной части заявления о выдаче с/приказа) – без госпошлины.'),
    ]),
    bodyParagraph([plain('Взыскать с '), debtorFioList]),
    bodyParagraph([plain('в пользу '), field(claimantName, 'наименование взыскателя')]),
    bodyParagraph([
      plain('расходы по уплате государственной пошлины в сумме '),
      dutyAmount ? label(dutyAmount) : placeholder('сумма госпошлины'),
      plain(' руб.'),
    ]),

    bodyParagraph([
      plain(
        'Судебный приказ выносится без судебного разбирательства и вызова сторон по результатам исследования представленных доказательств.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Должник вправе в течение 10 дней со дня получения копии судебного приказа предоставить судье свои возражения относительно его исполнения.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Судья отменяет судебный приказ, если от должника в установленный срок поступят возражения относительно его исполнения.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Вступившие в законную силу судебные акты могут быть обжалованы в суд кассационной инстанции лицами, участвующими в деле, и другими лицами, если их права, свободы и законные интересы нарушены судебным актом.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Судебный приказ является одновременно исполнительным документом (ст. 121 Гражданского процессуального кодекса РФ).'
      ),
    ]),
    bodyParagraph([plain('Судебный приказ может быть предъявлен к исполнению в течение трех лет.')]),

    { text: 'Фамилия, имя, отчество и дата рождения должника', bold: true, margin: [0, 16, 0, 2] },
    { text: [debtorFioBirthday] },

    { text: 'Место жительства и (или) регистрации должника', bold: true, margin: [0, 16, 0, 2] },
    { text: [debtorAddress] },

    {
      text: 'Наименование и адрес предприятия, учреждения, организации, в которой должник работает (или наименование и место заключения)',
      bold: true,
      margin: [0, 16, 0, 2],
    },
    { text: 'Неизвестно' },

    {
      text: 'Фамилия, имя, отчество (наименование) и место жительства или место нахождения взыскателя',
      bold: true,
      margin: [0, 16, 0, 2],
    },
    {
      text: [
        claimantFull
          ? plain(claimantFull)
          : placeholder(
              'все реквизиты взыскателя из шапки заявления о выдаче с/приказа (включая банковские реквизиты)'
            ),
      ],
    },
  ];

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
